css:
.referral-letter { font-size: 11pt; color: #000; }
.referral-letter header { display: flex; justify-content: space-between; border-bottom: 1.5pt solid #000; padding-bottom: 8pt; }
.referral-letter h1 { font-size: 18pt; margin: 0; }
.referral-letter .from { text-align: right; }
.referral-letter .facts { width: 100%; margin: 14pt 0; border-collapse: collapse; }
.referral-letter .facts th { width: 70pt; padding: 6pt 8pt 6pt 0; text-align: left; vertical-align: top; font-size: 9pt; text-transform: uppercase; letter-spacing: 0.05em; }
.referral-letter .facts td { padding: 6pt 0; vertical-align: top; }
.referral-letter h2 { margin: 14pt 0 4pt; font-size: 9pt; text-transform: uppercase; letter-spacing: 0.05em; }
.referral-letter .text { white-space: pre-wrap; }
.referral-letter .letter { margin-top: 14pt; }
.referral-letter .signature { width: 200pt; margin-top: 48pt; padding-top: 4pt; border-top: 1pt solid #000; font-size: 9pt; }

html:
{%- set patient = frappe.get_doc("Patient", doc.patient) -%}
{%- set practitioner = frappe.get_doc("Practitioner", doc.practitioner) if doc.practitioner else None -%}
{%- set clinic = frappe.db.get_single_value("Global Defaults", "default_company") -%}
{%- set clinic_phone = frappe.db.get_single_value("Engage Settings", "clinic_phone") -%}
<div class="referral-letter">
	<header>
		<div>
			<h1>Referral</h1>
			<p>{{ frappe.utils.format_date(doc.referral_date, "d MMMM yyyy") }}{% if doc.priority == "Urgent" %} · <strong>URGENT</strong>{% endif %}</p>
		</div>
		<div class="from">
			<strong>{{ clinic or "" }}</strong>
			{% if clinic_phone %}<br>Phone: {{ clinic_phone }}{% endif %}
			<br>Reference: {{ doc.name }}
		</div>
	</header>

	<table class="facts">
		<tr>
			<th>Patient</th>
			<td>
				<strong>{{ patient.patient_name }}</strong><br>
				Born {{ frappe.utils.format_date(patient.date_of_birth, "d MMMM yyyy") }}{% if patient.sex %} · {{ patient.sex }}{% endif %}<br>
				{% if patient.health_card_number %}Health card: {{ patient.health_card_number }} {{ patient.health_card_version or "" }} ({{ patient.health_card_province }})<br>{% endif %}
				{% if patient.mobile_phone or patient.home_phone %}Phone: {{ patient.mobile_phone or patient.home_phone }}<br>{% endif %}
				{% if patient.address_line1 %}{{ patient.address_line1 }}{% if patient.address_line2 %}, {{ patient.address_line2 }}{% endif %}, {{ patient.city or "" }} {{ patient.province or "" }} {{ patient.postal_code or "" }}{% endif %}
			</td>
		</tr>
		<tr>
			<th>To</th>
			<td>
				<strong>{{ doc.referred_to }}</strong>{% if doc.specialty %}, {{ doc.specialty }}{% endif %}
				{% if doc.referred_to_clinic %}<br>{{ doc.referred_to_clinic }}{% endif %}
			</td>
		</tr>
		<tr>
			<th>From</th>
			<td>
				{% if practitioner %}
				<strong>{{ practitioner.practitioner_name }}</strong>{% if practitioner.practitioner_type %}, {{ practitioner.practitioner_type }}{% endif %}
				{% if practitioner.ohip_billing_number %}<br>OHIP billing number: {{ practitioner.ohip_billing_number }}{% endif %}
				{% if practitioner.college_registration_number %}<br>Registration: {{ practitioner.college_registration_number }}{% endif %}
				{% else %}{{ clinic or "" }}{% endif %}
			</td>
		</tr>
	</table>

	<h2>Reason for referral</h2>
	<p class="text">{{ doc.reason or "" }}</p>
	{% if doc.letter %}<p class="text letter">{{ doc.letter }}</p>{% endif %}

	<p class="signature">{% if practitioner %}{{ practitioner.practitioner_name }}{% endif %}</p>
</div>
